From 716e9542911fe5d4e1710a104cff5ea0a8eac088 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 17:20:49 +0100
Subject: [PATCH] containments/desktop: open files with the second app on
 middle-click

Middle-clicking a file on the desktop did nothing, while Dolphin opens it
with the second application associated with its type. Do the same in
Folder View, with Shift for the third one, like Dolphin does.

BUG: 507880
---
 .../package/contents/ui/FolderView.qml        | 20 +++++++++++++++-
 .../desktop/plugins/folder/foldermodel.cpp    | 23 +++++++++++++++++++
 .../desktop/plugins/folder/foldermodel.h      |  1 +
 3 files changed, 43 insertions(+), 1 deletion(-)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..989f3853ad 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -212,7 +212,7 @@ FocusScope {

         acceptedButtons: root.inPanel
             ? (Qt.LeftButton | Qt.MiddleButton | Qt.RightButton | Qt.BackButton)
-            : (Qt.LeftButton | Qt.RightButton)
+            : (Qt.LeftButton | Qt.MiddleButton | Qt.RightButton)

         hoverEnabled: true

@@ -243,6 +243,14 @@ FocusScope {
                 return;
             }

+            // Middle-click opens items in onReleased; on empty space it goes to containment actions
+            if (mouse.button === Qt.MiddleButton) {
+                const middlePos = mapToItem(gridView.contentItem, mouse.x, mouse.y);
+                const middleItem = gridView.safeItemAt(middlePos.x, middlePos.y);
+                mouse.accepted = !!middleItem && !middleItem.blank;
+                return;
+            }
+
             scrollArea.focus = true;

             if (mouse.buttons & Qt.BackButton) {
@@ -330,6 +338,16 @@ FocusScope {
         onCanceled: pressCanceled()

         onReleased: mouse => {
+            if (mouse.button === Qt.MiddleButton) {
+                const middlePos = mapToItem(gridView.contentItem, mouse.x, mouse.y);
+                const middleItem = gridView.safeItemAt(middlePos.x, middlePos.y);
+                if (middleItem && !middleItem.blank) {
+                    middleItem.hideToolTip();
+                    dir.runWithAlternativeApplication(positioner.map(middleItem.index), mouse.modifiers & Qt.ShiftModifier);
+                }
+                return;
+            }
+
             // if we click on an item, cancel the current selection and select just the clicked icon
             // the cachedRectangleSelection guards this release being associated with an existing drag
             if (!gridView.cachedRectangleSelection && hoveredItem && !hoveredItem.blank && mouse.button !== Qt.RightButton) {
diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..8e694d467c 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -42,6 +42,7 @@
 #include <QTimer>
 #include <qplatformdefs.h>

+#include <KApplicationTrader>
 #include <KAuthorized>
 #include <KConfigGroup>
 #include <KCoreDirLister>
@@ -51,6 +52,7 @@
 #include <KFileCopyToMenu>
 #include <KFileItemActions>
 #include <KFileItemListProperties>
+#include <KIO/ApplicationLauncherJob>
 #include <KIO/CopyJob>
 #include <KIO/DeleteJob>
 #include <KIO/DeleteOrTrashJob>
@@ -863,6 +865,27 @@ void FolderModel::run(int row)
     job->start();
 }

+void FolderModel::runWithAlternativeApplication(int row, bool third)
+{
+    if (row < 0) {
+        return;
+    }
+
+    const KFileItem item = itemForIndex(index(row, 0));
+    const KService::List services = KApplicationTrader::queryByMimeType(item.mimetype());
+    const int serviceIndex = third ? 2 : 1;
+
+    if (item.isDir() || services.count() <= serviceIndex) {
+        run(row);
+        return;
+    }
+
+    auto job = new KIO::ApplicationLauncherJob(services.at(serviceIndex));
+    job->setUrls({item.targetUrl()});
+    job->setUiDelegate(KIO::createDefaultJobUiDelegate(KJobUiDelegate::AutoHandlingEnabled, nullptr));
+    job->start();
+}
+
 void FolderModel::runSelected()
 {
     const QModelIndexList indexes = m_selectionModel->selectedIndexes();
